<?php
require_once __DIR__.'/../config/auth.php';require_login();$disciplina=trim($_GET['disciplina']??'');$sql='SELECT * FROM materiais_estudo';$params=[];if($disciplina){$sql.=' WHERE disciplina=?';$params[]=$disciplina;}$sql.=' ORDER BY created_at DESC';$s=db()->prepare($sql);$s->execute($params);$materials=$s->fetchAll();$subjects=db()->query('SELECT DISTINCT disciplina FROM materiais_estudo ORDER BY disciplina')->fetchAll(PDO::FETCH_COLUMN);$pageTitle='Estudos';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/dashboard-nav.php';
?><p class="subtext">Materiais preparados pela equipe para apoiar seus estudos.</p><form class="filterbar"><div class="searchbar"><select name="disciplina"><option value="">Todas as disciplinas</option><?php foreach($subjects as $subject):?><option <?=$disciplina===$subject?'selected':''?>><?=e($subject)?></option><?php endforeach;?></select></div><button class="btn btn-small">Filtrar</button></form><div class="book-grid"><?php foreach($materials as $m):?><article class="book-card"><div class="cover cover-placeholder" style="height:150px"><?=e($m['disciplina'])?></div><div class="book-info"><span class="badge"><?=e($m['disciplina'])?></span><h3 style="margin-top:11px"><?=e($m['titulo'])?></h3><p><?=e(mb_strimwidth((string)$m['descricao'],0,120,'…'))?></p><?php if($m['arquivo_pdf']):?><a class="btn btn-small" href="<?=base_url('aluno/ler-estudo.php?id='.(int)$m['id'])?>">Abrir PDF</a><?php endif;?><?php if($m['link_externo']):?><a class="btn btn-small btn-outline" target="_blank" rel="noopener" href="<?=e($m['link_externo'])?>">Abrir link</a><?php endif;?></div></article><?php endforeach;?><?php if(!$materials):?><div class="empty">Ainda não há materiais nesta área.</div><?php endif;?></div><?php require __DIR__.'/../includes/dashboard-footer.php';?>
